/**
 * The generated drug index: Indian brand tokens → active salts, and
 * DrugBank-derived salt pairs → interaction types.
 *
 * Data is generated by scripts/build-drug-index.mjs into raw text modules so
 * neither tsc nor the bundler has to build a 135,000-key object type.
 * Everything here is server-side only.
 */
import { BRANDS_RAW, AMBIGUOUS_RAW, SUGGEST_RAW } from "./generated/brands.data";
import { DDI_RAW } from "./generated/ddi.data";
import { DRUG_INDEX_META } from "./generated/meta";
import { canonicalSalt, normalizeBrand } from "./drug-names";

export { DRUG_INDEX_META };

const BRANDS = new Map<string, string[]>();
for (const line of BRANDS_RAW.split("\n")) {
  const tab = line.indexOf("\t");
  if (tab <= 0) continue;
  BRANDS.set(line.slice(0, tab), line.slice(tab + 1).split("+"));
}

const AMBIGUOUS = new Set(AMBIGUOUS_RAW.split("\n").filter(Boolean));

/** Only brands seen on several products are offered as spelling hints. */
const SUGGEST_BY_LETTER = new Map<string, string[]>();
for (const key of SUGGEST_RAW.split("\n")) {
  if (!key) continue;
  const bucket = SUGGEST_BY_LETTER.get(key[0]) ?? [];
  bucket.push(key);
  SUGGEST_BY_LETTER.set(key[0], bucket);
}

const DDI = new Map<string, string[]>();
for (const line of DDI_RAW.split("\n")) {
  const tab = line.indexOf("\t");
  if (tab <= 0) continue;
  DDI.set(line.slice(0, tab), line.slice(tab + 1).split(";"));
}

export const INTERACTION_SOURCE = {
  name: "DrugBank 5.1 — DDI dataset (Yu, 2020)",
  url: "https://doi.org/10.17632/md5czfsfnd.1",
};

/**
 * Look a brand token up in the 253,973-product index.
 * `known` is false when the products disagree on composition — the caller
 * must then show the salt for review rather than silently trusting it.
 */
export function indexedSalts(brand: string): { salts: string[]; known: boolean } | null {
  const key = normalizeBrand(brand);
  if (!key) return null;
  const salts = BRANDS.get(key);
  if (!salts) return null;
  return { salts, known: !AMBIGUOUS.has(key) };
}

export function indexedBrandCount(): number {
  return BRANDS.size;
}

/** Interaction types for a salt pair, or null when DrugBank has no record. */
export function interactionTypes(a: string, b: string): string[] | null {
  const ka = canonicalSalt(a);
  const kb = canonicalSalt(b);
  if (!ka || !kb || ka === kb) return null;
  return DDI.get([ka, kb].sort().join("|")) ?? null;
}

/**
 * The dataset has no severity column, so severity is inferred from the type
 * wording. Curated rules keep their own, stronger wording and win first.
 */
const HIGH_RISK =
  /bleed|arrhythm|torsade|\bqt\b|serotonin|seizure|hypoglyc|nephrotox|hepatotox|agranulocyt|pancytopen|respiratory depression|cardiac|hyperkala|hyperkal|rhabdomyolysis|myopathy|contracept/;

export function interactionSeverity(types: string[]): "high" | "moderate" {
  return types.some((t) => HIGH_RISK.test(t)) ? "high" : "moderate";
}

function distance(a: string, b: string): number {
  if (Math.abs(a.length - b.length) > 2) return 3;
  const cols = b.length + 1;
  let prev = Array.from({ length: cols }, (_, j) => j);
  let curr = new Array<number>(cols).fill(0);

  for (let i = 1; i <= a.length; i += 1) {
    curr[0] = i;
    for (let j = 1; j < cols; j += 1) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost);
    }
    [prev, curr] = [curr, prev];
  }
  return prev[cols - 1];
}

/**
 * Suggest a known brand for an OCR spelling, never replace it.
 * Only close matches with the same first letter qualify; a wrong guess about
 * a drug name is worse than no guess, so this is shown as a question.
 */
export function suggestIndexedBrand(brand: string): string | null {
  const key = normalizeBrand(brand);
  if (key.length < 4) return null;
  if (BRANDS.has(key)) return key;

  const allowed = key.length >= 7 ? 2 : 1;
  let best: { name: string; d: number } | null = null;

  for (const name of SUGGEST_BY_LETTER.get(key[0]) ?? []) {
    if (Math.abs(name.length - key.length) > allowed) continue;
    const d = distance(key, name);
    if (d <= allowed && (!best || d < best.d)) best = { name, d };
  }

  return best?.name ?? null;
}
